(()=>{
'use strict';
const base='assets/pokemon-table/',D=PokemonTableData,C=PokemonTableCore,A=PokemonBattleAudio;
let local=null,snapshot=null,mode=null,token=null,pollTimer=0,clockTimer=0,cpuTimer=0,epoch=0,lastKey='',lastPhase='',busy=false,offset=0,fxStops=[],fxTimers=[],fxAnimations=[];
let roomConnection=null;
const appNode=()=>document.getElementById('app');
function cancelFX(){fxStops.forEach(f=>f());fxStops=[];fxTimers.forEach(clearTimeout);fxTimers=[];fxAnimations.forEach(a=>a.cancel());fxAnimations=[];}
function stop(){document.querySelector('.pk-type-dialog')?.remove();epoch++;clearTimeout(pollTimer);clearInterval(clockTimer);clearTimeout(cpuTimer);cancelFX();if(roomConnection){roomConnection.close();roomConnection=null;}else if(token){fetch('/api/pokemon/leave',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:'{}',keepalive:true}).catch(()=>{});}token=null;local=null;snapshot=null;mode=null;lastKey='';lastPhase='';busy=false;}
function artwork(c){const crop=c.artCrop,src=base+(c.art||c.id+'-art-v1.webp');if(!crop)return '<img class="pk-art" src="'+src+'" alt="'+c.name+'" draggable="false">';return '<span class="pk-art-window"><img class="pk-art-crop" src="'+src+'" alt="'+c.name+'" draggable="false" style="width:'+crop.sourceWidth/crop.width*100+'%;height:'+crop.sourceHeight/crop.height*100+'%;left:'+(-crop.x/crop.width*100)+'%;top:'+(-crop.y/crop.height*100)+'%"></span>';}
function card(c,action='',hp=c.hp??50,showHealth=false){const t=D.types[c.type];return '<div class="pk-unit" data-unit="'+c.id+'"><button class="pk-card" style="--type:'+t.color+'" '+(action?'data-'+action+'="'+c.id+'"':'disabled')+' aria-label="'+c.name+(showHealth?', '+hp+' de vida':'')+', tipo '+t.name+'">'+artwork(c)+typeIcon(c.type,'pk-type')+'<span class="pk-hit-overlay"></span></button>'+(showHealth?'<div class="pk-health" aria-label="Vida '+hp+' de 50"><div class="pk-health-track"><i style="width:'+hp*2+'%"></i></div><b>'+hp+'</b></div>':'')+'</div>';}
function cardBack(){return '<div class="pk-card pk-card-back"><img src="'+base+'pocket-card-back.png" alt="Carta do oponente virada para baixo" draggable="false"></div>';}
function escapeText(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function shell(title,hint,body){title=escapeText(title);hint=escapeText(hint);appNode().innerHTML='<section class="pk-page pk-live"><div class="pk-top"><button id="pk-home">← Jogos</button><span>BATALHA POKÉMON</span><div><button id="pk-type-help">Tipos</button> <button id="pk-sound" aria-pressed="'+A.enabled+'">Som '+(A.enabled?'ligado':'desligado')+'</button> <button id="pk-reset">← Coleção</button></div></div><div class="pk-intro"><h1>'+title+'</h1><p role="status">'+hint+'</p></div>'+body+'</section>';if(roomConnection){const badge=document.createElement('small');badge.className='pk-transport';badge.textContent=roomConnection.label;appNode().querySelector('.pk-intro').append(badge);}appNode().querySelector('#pk-type-help').onclick=typeHelp;appNode().querySelector('#pk-home').onclick=home;appNode().querySelector('#pk-reset').onclick=open;appNode().querySelector('#pk-sound').onclick=e=>{A.unlock();const on=A.toggle();e.target.textContent='Som '+(on?'ligado':'desligado');e.target.setAttribute('aria-pressed',on);};}
function open(){stop();for(const a of Object.values(PokemonAttacksData))for(const src of a.frames){const i=new Image();i.src=src;}document.body.dataset.section='pokemon';window.scrollTo(0,0);shell('Uma mesa, muitas aventuras','Escolha como jogar e monte seu time.', '<div class="pk-modes"><button class="pk-primary" id="pk-solo">1 pessoa · contra o computador</button><button class="pk-primary" id="pk-online">2 pessoas · online</button></div><details class="pk-rules"><summary>Como jogar e vantagens dos tipos</summary><p>Doze cartas: dois Lutadores, dois Normais, uma de cada outro tipo e uma extra aleatória, exceto Lutador e Normal. Cada pessoa escolhe seis, alternadamente. Na batalha, você tem 5 segundos por escolha; ao acabar o tempo, o jogo escolhe uma carta disponível.</p><p>Cada Pokémon começa com 50 de vida. Super efetivo: 50 de dano; efetivo: 25; não efetivo: 12. A vida permanece entre rodadas. Ambos atacam, mesmo se o primeiro golpe derrotar o adversário. São até 10 rodadas. Vence quem tiver mais Pokémon vivos, depois mais vida total; se ambos forem iguais, empate.</p>'+chart()+'<p><a href="pokemon-attacks.html">Ver animações</a> · <a href="pokemon-sources.html" target="_blank" rel="noopener">Cartas e fontes</a></p></details><div class="pk-gallery">'+D.cards.map(c=>card(c,'preview')).join('')+'</div>');appNode().querySelector('#pk-solo').onclick=startSolo;appNode().querySelector('#pk-online').onclick=onlineMenu;appNode().querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>preview(b.dataset.preview));}
function typeIcon(t,cls=''){const type=D.types[t],c=type.iconCrop;if(c)return '<span class="pk-metal-icon '+cls+'" role="img" aria-label="'+type.name+'" title="'+type.name+'" style="background-image:url('+base+c.source+');background-size:'+c.sourceWidth/c.size*100+'% '+c.sourceHeight/c.size*100+'%;background-position:'+c.x/(c.sourceWidth-c.size)*100+'% '+c.y/(c.sourceHeight-c.size)*100+'%"></span>';return '<img class="'+cls+'" src="'+base+t+'-official.png" alt="'+type.name+'" title="'+type.name+'">';}
function chart(){return '<div class="pk-type-chart"><table><thead><tr><th scope="col">Tipo</th><th scope="col">Força</th><th scope="col">Fraqueza</th></tr></thead><tbody>'+C.types.map(t=>{const force=C.strong[t],weak=C.types.filter(attacker=>C.strong[attacker].includes(t));return '<tr><th scope="row">'+typeIcon(t)+'</th><td>'+(force.map(typeIcon).join('')||'<span aria-label="Nenhuma">—</span>')+'</td><td>'+(weak.map(typeIcon).join('')||'<span aria-label="Nenhuma">—</span>')+'</td></tr>';}).join('')+'</tbody></table></div>';}
function typeHelp(){if(document.querySelector('.pk-type-dialog'))return;const dialog=document.createElement('dialog');dialog.className='pk-type-dialog';dialog.setAttribute('aria-label','Forças e fraquezas dos tipos');dialog.innerHTML='<button class="pk-close" aria-label="Fechar tabela" autofocus>×</button><h2>Forças e fraquezas</h2><p>Força: causa 50 de dano. Fraqueza: recebe 50 de dano.<br>— indica nenhuma entre os tipos atuais.</p>'+chart()+'<small>Durante a rodada, o tempo de escolha continua contando.</small>';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close();};dialog.onclose=()=>{dialog.remove();appNode().querySelector('#pk-type-help')?.focus();};dialog.showModal();}
function startSolo(){stop();A.unlock();mode='solo';local=C.create(D.cards);accept({...C.view(local,0),serverNow:Date.now()});startClock();}
async function api(path,data){if(data&&path==='action'&&Number.isInteger(snapshot?.generation))data={...data,generation:snapshot.generation};if(roomConnection)return roomConnection.request(path,data);const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),6000);try{const r=await fetch('/api/pokemon/'+path,{method:data?'POST':'GET',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},...(data?{body:JSON.stringify(data)}:{}),signal:controller.signal});const v=await r.json();if(!r.ok)throw Object.assign(Error(v.error||'Falha na conexão'),{status:r.status});return v;}finally{clearTimeout(timeout);}}
function roomOptions(){return {game:'pokemon',back:open,matchmaking:()=>startOnline(),start:startRoom};}
function onlineMenu(){stop();document.body.dataset.section='pokemon';OnlineRooms.menu(roomOptions());}
async function startRoom(session){stop();A.unlock();mode='online';token=session.token;roomConnection=session.connection;accept(session.state);startClock();poll(epoch);}
window.PokemonOnlineInvite=code=>{stop();document.body.dataset.section='pokemon';OnlineRooms.invitation(roomOptions(),code);};
async function rematch(){if(busy)return;busy=true;const run=epoch;try{const s=await api('action',{kind:'rematch'});if(run===epoch)accept(s);}catch(e){if(run===epoch){const el=appNode().querySelector('.pk-intro p');if(el)el.textContent=e.message;}}finally{if(run===epoch)busy=false;}}
async function startOnline(){stop();A.unlock();mode='online';const run=epoch;shell('Aguardando oponente…','Conectando à fila de jogadores.','<div class="pk-wait">✦</div>');try{const s=await api('join',{});if(run!==epoch){fetch('/api/pokemon/leave',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+s.token},body:'{}',keepalive:true}).catch(()=>{});return;}token=s.token;accept(s);startClock();poll(run);}catch(e){if(run===epoch)showError('Não foi possível entrar na fila. Confira a conexão e se o servidor foi atualizado.');}}
async function poll(run){if(run!==epoch||!token)return;try{const s=await api('action',{kind:'heartbeat',active:!document.hidden&&navigator.onLine,phase:snapshot?.phase,round:snapshot?.round,deadline:snapshot?.deadline});if(run!==epoch)return;accept(s);}catch(e){if(run!==epoch)return;if(e.status===401){showError('A sessão terminou. Entre novamente para procurar outro oponente.');return;}const el=appNode().querySelector('.pk-connection');if(el)el.textContent='Reconectando…';cancelFX();if(snapshot){snapshot={...snapshot,phase:'paused',deadline:null};lastKey='';renderMatch();}}if(run===epoch)pollTimer=setTimeout(()=>poll(run),400);}
function showError(msg){stop();document.body.dataset.section='pokemon';shell('Não foi possível continuar',msg,'<button class="pk-primary" id="pk-retry">Voltar à coleção</button>');appNode().querySelector('#pk-retry').onclick=open;}
function startClock(){clockTimer=setInterval(()=>{if(mode==='solo'&&local){if(C.tick(local,Date.now()))accept({...C.view(local,0),serverNow:Date.now()});}updateClock();},80);}
function updateClock(){const el=appNode().querySelector('#pk-seconds');if(el&&snapshot)el.textContent=Math.max(0,Math.ceil((snapshot.deadline-Date.now()-offset)/1000));const bar=appNode().querySelector('.pk-countdown i');if(bar&&snapshot)bar.style.width=Math.max(0,Math.min(100,(snapshot.deadline-Date.now()-offset)/C.CHOOSE_MS*100))+'%';}
function accept(s){if(s.lobby?.closed){showError(s.reason||'A outra pessoa saiu.');return;}if(snapshot&&Number.isFinite(s.revision)&&Number.isFinite(snapshot.revision)&&s.revision<snapshot.revision)return;offset=s.serverNow-Date.now();snapshot=s;const key=[s.phase,s.revision,s.you,s.choices?.[s.you],s.rematch?.join(','),s.generation].join(':');if(key!==lastKey){lastKey=key;renderMatch();}if(mode==='solo')scheduleCPU();}
function scheduleCPU(){clearTimeout(cpuTimer);if(!local)return;if(local.phase==='draft'&&local.turn===1){cpuTimer=setTimeout(()=>{if(mode!=='solo'||local.phase!=='draft'||local.turn!==1)return;C.draft(local,1,local.pool[Math.floor(Math.random()*local.pool.length)].id);accept({...C.view(local,0),serverNow:Date.now()});},450);}else if(local.phase==='choose'&&!local.choices[1]){const a=C.available(local,1);C.choose(local,1,a[Math.floor(Math.random()*a.length)].id);accept({...C.view(local,0),serverNow:Date.now()});}}
async function act(kind,id){if(busy||!snapshot)return;A.unlock();busy=true;const run=epoch;try{if(mode==='solo'){if(kind==='draft')C.draft(local,0,id);else C.choose(local,0,id);accept({...C.view(local,0),serverNow:Date.now()});}else{const s=await api('action',{kind,id,round:snapshot.round,picks:snapshot.picks});if(run===epoch)accept(s);}}catch(e){if(run===epoch&&e.status!==409){const el=appNode().querySelector('.pk-connection');if(el)el.textContent='Falha ao enviar. Tente novamente.';}}finally{if(run===epoch)busy=false;}}
function renderMatch(){cancelFX();const s=snapshot;if(s.phase!==lastPhase){lastPhase=s.phase;window.scrollTo(0,0);}if(s.phase==='waiting'){shell('Aguardando oponente…','Assim que outra pessoa entrar no modo online, a partida começa.','<div class="pk-wait">✦</div><p class="pk-connection">Você está na fila.</p>');return;}const me=s.you,other=1-me,mine=s.hands[me],theirs=s.hands[other],alive=h=>h.filter(c=>c.hp>0).length;
 const totals=C.standings(s);const score='<div class="pk-score">Você <b>'+alive(mine)+' × '+alive(theirs)+'</b> '+(mode==='solo'?'Computador':'Oponente')+'</div><p class="pk-totals">Pokémon vivos: '+totals[me].alive+' × '+totals[other].alive+' · Vida restante: '+totals[me].hp+' × '+totals[other].hp+'</p>';
 const countdown='<div class="pk-clock"><b id="pk-seconds">5</b><span>segundos para escolher</span><div class="pk-countdown"><i></i></div></div>';
 if(s.phase==='paused'||s.phase==='ready'){shell(s.phase==='paused'?'Partida pausada':'Preparando a '+s.round+'ª rodada',s.phase==='paused'?'Aguardando os dois aparelhos reconectarem. Nenhuma escolha automática durante a pausa.':'Aguardando os dois jogadores estarem prontos para escolher.',score+'<div class="pk-wait">⌛</div><p class="pk-connection"></p>');}
 else if(s.phase==='draft'){const turn=s.turn===me;shell('Monte seu time · '+mine.length+'/6',turn?'Sua vez de escolher':'O oponente está escolhendo.','<div class="pk-gallery pk-pool">'+s.pool.map(c=>card(c,turn?'draft':'')).join('')+'</div><div class="pk-own-mini">'+mine.map(c=>card(c)).join('')+'</div><p class="pk-connection"></p>');}
 else if(s.phase==='choose'){shell(s.round+'ª RODADA · até 10',s.choices[me]?'Carta escolhida! Aguardando o oponente.':'Escolha o Pokémon que vai atacar.',score+'<div class="pk-opponent-row">'+theirs.filter(c=>c.hp>0).map(()=>cardBack()).join('')+'</div>'+countdown+'<div class="pk-gallery pk-hand-play">'+mine.filter(c=>c.hp>0).map(c=>card(c,s.choices[me]?'':'choose',c.hp,true)).join('')+'</div><p class="pk-connection"></p>');}
 else if(s.phase==='countdown'){shell(s.round+'ª RODADA · até 10','Prepare-se! As cartas serão reveladas juntas.',score+'<div class="pk-reveal-count" id="pk-seconds">3</div>');}
 else if(s.phase==='result'){const r=s.result;shell(s.round+'ª RODADA · até 10','Os dois Pokémon atacam!',score+'<div class="pk-arena"><div class="pk-fighter" id="pk-self"><span>Você</span>'+card(r.cards[me],'',r.cards[me].hp,true)+'</div><div class="pk-versus">×</div><div class="pk-fighter" id="pk-enemy"><span>'+(mode==='solo'?'Computador':'Oponente')+'</span>'+card(r.cards[other],'',r.cards[other].hp,true)+'</div><div id="pk-effects"></div></div><p class="pk-damage-caption" role="status"></p><p class="pk-connection">Próxima rodada em instantes…</p>');animateRound(r,me);}
 else {const won=s.winner===me;shell(s.winner===null?'Partida interrompida':s.winner==='draw'?'Empate!':won?'Você venceu!':'O oponente venceu!',s.reason||'Batalha encerrada após '+s.round+' rodadas.',score+'<div class="pk-end">'+(s.winner==='draw'?'🤝':won?'🏆':s.winner===null?'✨':'<img class="pk-defeat-psyduck" src="'+base+'psyduck-defeat.png" alt="Psyduck segurando a cabeça com as duas mãos">')+'</div><button class="pk-primary" id="pk-again">Jogar novamente</button>');const again=appNode().querySelector('#pk-again');if(s.rematch?.[me]){again.textContent='Aguardando o outro jogador…';again.disabled=true;}else if(s.rematch?.[other])again.textContent='Aceitar e jogar novamente';appNode().querySelector('#pk-again').onclick=()=>mode==='online'?rematch():startSolo();}
 appNode().querySelectorAll('[data-draft]').forEach(b=>b.onclick=()=>act('draft',b.dataset.draft));appNode().querySelectorAll('[data-choose]').forEach(b=>b.onclick=()=>act('choose',b.dataset.choose));updateClock();}
function animateRound(r,me){const other=1-me,elapsed=Math.max(0,Date.now()+offset-r.at);const later=(ms,fn)=>{if(ms<elapsed-100)return;fxTimers.push(setTimeout(fn,Math.max(0,ms-elapsed)));};
 function hit(target,attacker,index){const el=appNode().querySelector(target);if(!el)return;const dmg=r.damage[attacker],hp=r.hp[index];el.style.setProperty('--hit',D.types[r.cards[attacker].type].color);el.classList.add('pk-hit');el.querySelector('.pk-health i').style.width=hp*2+'%';el.querySelector('.pk-health b').textContent=hp;el.querySelector('.pk-health').setAttribute('aria-label','Vida '+hp+' de 50');A.play(r.cards[attacker].type,true);appNode().querySelector('.pk-damage-caption').textContent=(dmg===50?'Super efetivo!':dmg===12?'Não efetivo':'Efetivo')+' −'+dmg;fxTimers.push(setTimeout(()=>el.classList.remove('pk-hit'),550));}
 function launch(from,to,type){const arena=appNode().querySelector('.pk-arena'),a=appNode().querySelector(from+' .pk-card'),b=appNode().querySelector(to+' .pk-card');if(!a||!b)return;const rect=arena.getBoundingClientRect(),ra=a.getBoundingClientRect(),rb=b.getBoundingClientRect();const effect=document.createElement(type==='steel'?'span':'img');effect.className='pk-projectile'+(type==='steel'?' pk-metal-attack':'');if(type==='steel'){effect.setAttribute('aria-hidden','true');effect.innerHTML='<i></i><i></i><i></i>';}else effect.alt='';effect.style.left=(ra.left+ra.width/2-rect.left)+'px';effect.style.top=(ra.top+ra.height/2-rect.top)+'px';appNode().querySelector('#pk-effects').append(effect);const id=type==='normal'?'fighting':type;if(type!=='steel')fxStops.push(PokemonAttacks.play(effect,id,{loops:8}));A.play(type);const dx=rb.left+rb.width/2-ra.left-ra.width/2,dy=rb.top+rb.height/2-ra.top-ra.height/2;const mirror=(dx<0&&(type==='water'||type==='fighting'||type==='normal'))?' scaleX(-1)':'';const animation=effect.animate([{transform:'translate(-50%,-50%) scale(.45)'+mirror,opacity:0},{offset:.15,transform:'translate(-50%,-50%) scale(.85)'+mirror,opacity:1},{transform:'translate(calc(-50% + '+dx+'px),calc(-50% + '+dy+'px)) scale(1)'+mirror,opacity:1}],{duration:900,fill:'forwards',easing:'ease-in'});fxAnimations.push(animation);fxTimers.push(setTimeout(()=>effect.remove(),950));}
 // Late/reconnected clients display the already-applied health without replaying old hits.
 if(elapsed>1150){const el=appNode().querySelector('#pk-enemy');el.querySelector('.pk-health i').style.width=r.hp[other]*2+'%';el.querySelector('.pk-health b').textContent=r.hp[other];}
 if(elapsed>3350){const el=appNode().querySelector('#pk-self');el.querySelector('.pk-health i').style.width=r.hp[me]*2+'%';el.querySelector('.pk-health b').textContent=r.hp[me];}
 later(250,()=>launch('#pk-self','#pk-enemy',r.cards[me].type));later(1150,()=>hit('#pk-enemy',me,other));later(2450,()=>launch('#pk-enemy','#pk-self',r.cards[other].type));later(3350,()=>hit('#pk-self',other,me));
 for(const [selector,i] of [['#pk-self',me],['#pk-enemy',other]])if(r.hp[i]===0){if(elapsed>4500)appNode().querySelector(selector).classList.add('pk-fainted');else later(4500,()=>appNode().querySelector(selector)?.classList.add('pk-fainted'));}}
function preview(id){const c=D.cards.find(c=>c.id===id),dialog=document.createElement('dialog');dialog.className='pk-preview';dialog.innerHTML='<button class="pk-close" autofocus aria-label="Fechar carta">×</button>'+card(c)+'<h2>'+c.name+'</h2><p>'+D.types[c.type].name+' · '+c.set+' · '+c.number+'</p>'+(c.original?'<a href="'+base+c.original+'" target="_blank" rel="noopener">Ver carta original completa ↗</a>':'');appNode().append(dialog);dialog.querySelector('.pk-close').onclick=()=>dialog.close();dialog.onclose=()=>{dialog.remove();appNode().querySelector('[data-preview="'+id+'"]')?.focus();};dialog.onclick=e=>{if(e.target===dialog)dialog.close();};dialog.showModal();}
const oldHome=home;home=function(){stop();oldHome();const cards=appNode().querySelector('.game-cards');if(!cards)return;cards.insertAdjacentHTML('beforeend','<button class="game-card pk-portal" id="pk-open"><div class="game-cover pk-cover"><img src="'+base+'table-v1.webp" alt="Mesa redonda na grama"><div class="pk-cover-cards">'+['jolteon','pikachu','umbreon'].map(n=>{const c=D.cards.find(c=>c.id===n);return '<img src="'+base+(c.art||n+'-art-v1.webp')+'" alt="'+c.name+'">';}).join('')+'</div><span class="cover-badge">✦ BATALHA DE CARTAS</span></div><div class="game-card-copy"><small>ESCOLHA SEU TIME</small><h2>Pokémon <span>↗</span></h2><p>Uma batalha para jogar sozinho ou com outra pessoa.</p></div></button>');appNode().querySelector('#pk-open').onclick=open;};const oldCatalog=showCatalog;showCatalog=function(){stop();oldCatalog();};document.addEventListener('visibilitychange',()=>{if(mode==='online'&&token&&document.hidden)api('action',{kind:'heartbeat',active:false}).catch(()=>{});});window.addEventListener('pagehide',stop);home();
})();
